// ===== src/content_scripts/Spezialdiensteingabe.js =====
__SCRIPTS["src/content_scripts/Spezialdiensteingabe.js"] = function () {
$(document).ready(function() {
var d = new Date();
var today = new Date();
var dd = today.getDate();
var mm = today.getMonth()+1;

var yyyy = today.getFullYear();
if(dd<10){
    dd='0'+dd;
}
if(mm<10){
    mm='0'+mm;
}
var today = dd+'.'+mm+'.'+yyyy;

$("input[name='Stundenbis']").val(d.getHours());
$("input[name='Minutenbis']").val((d.getMinutes()<10?'0':'') + d.getMinutes());
$("input[name='Datum']").val(today);
$("select[name='KennzifferID']>option[value*='Admin_BS_Funkt']").attr('selected', true);
$("input[name='ListeEingabe']").attr('checked', true);
});

};

// ===== src/content_scripts/AmbulancesEdit.js =====
__SCRIPTS["src/content_scripts/AmbulancesEdit.js"] = function () {
$(document).ready(function() {

  console.log("AmbulancesEdit.js started....");
  $("tr.DutyRosterHeader").first().children().last().css("width","2%");

  var scrapeAmbulance = function() {
    var ambulance = {
      url: window.location.href,
      queryDate: new Date()
    };
    ambulance.title = $('h2:first').text().trim() || $('#ctl00_main_m_AmbulanceDisplay_m_Description').text().trim();
    ambulance.id_original = $('#ctl00_main_m_AmbulanceDisplay_m_Number').text().trim();
    ambulance.sub = parseInt($('#ctl00_main_m_AmbulanceDayDisplay_m_SubNumber').text().trim());
    ambulance.id = ambulance.id_original.replace('/', '_') + '_' + ambulance.sub;
    ambulance.description =
        'URL: '+ambulance.url+'\r\n'+
        'Einsatzbeginn: '+$('#ctl00_main_m_AmbulanceDayDisplay_m_Start', '').text()+'\r\n'+
        'EB vor Ort: '+$('#ctl00_main_m_AmbulanceDayDisplay_m_StartWork', '').text()+'\r\n'+
        'Geplantes Ende: '+$('#ctl00_main_m_AmbulanceDayDisplay_m_EndWork', '').text()+'\r\n\r\n'+
        $('#ctl00_main_m_AmbulanceDisplay_m_Webinfo').text().trim();
    console.log(ambulance.description);
    ambulance.address = $('#ctl00_main_m_AmbulanceDisplay_m_Ort').text();
    ambulance.start = moment($('#ctl00_main_m_AmbulanceDayDisplay_m_Start', '').text().split(',')[1].trim(), 'D.M.YYYY H:mm', 'de').toDate();
    ambulance.startwork = moment($('#ctl00_main_m_AmbulanceDayDisplay_m_StartWork', '').text().split(',')[1].trim(), 'D.M.YYYY H:mm', 'de').toDate();
    ambulance.end = moment($('#ctl00_main_m_AmbulanceDayDisplay_m_EndWork').text().split(',')[1].trim(), 'D.M.YYYY H:mm', 'de').toDate();

    /* var headers = $('table[id=ctl00_main_m_AmbulanceDayInfo_ctl00_m_Table] tr.DutyRosterHeader').find('td').map(function() { 
      return $(this).text().trim();
    }).get(); */

    ambulance.employees = [];
    $("table[id^='ctl00_main_m_AmbulanceDayInfo_ctl'][id$='_m_AmbulanceFunctionDisplay_m_Table']").each(function() {
      var employee = {};
      var firstRow = $(this).find('tr').first().find('td');
      var verwendung = firstRow.first().text().split('/');
      employee.Position = verwendung[0].trim();
      employee.Funktion = verwendung[1].trim();
      employee.dNr = parseInt(firstRow.eq(1).text()) || parseInt(firstRow.eq(1).find('input').first().val());
      var name = getEmployeeDataFromLink(firstRow.eq(2).find('a').first(), 'EmployeeID');
      employee.Name = name;
      employee.Dienststelle = firstRow.eq(3).text().trim();
      var abfahrt = firstRow.eq(4).text().split('(');
      employee.Abfahrt = {};
      employee.Abfahrt.Ort = abfahrt[0].trim();
      employee.Abfahrt.Zeitpunkt = moment(abfahrt[1].replace(')', '').trim(), 'D.MM.YYYY HH:mm').toDate();
      employee.Anmerkung = $(this).find('span[id$="_m_AmbulanceFunctionDisplay_m_FunctionNotes"]').first().text() || $(this).find('input[id$="m_EditFunctionNotes"]').first().val();
      ambulance.employees.push(employee);
    });

    // Termin export unter der Überschrift für single event Termine
    var cal = createCalElement(ambulance);
    $('h1:first').append('<div id="exportCal_' + ambulance.id + '"></div>');
    $('#exportCal_' + ambulance.id).append(cal);

    return ambulance;
  };

  function _getEmailsfromEmployeeData(employee, displayName) {
    var emails = Array();
    // email Format: "Fred Foo"<foo@example.com>
    $.each(employee.contacts, function() {
      if(this.k.indexOf("EMAIL") === 0) {
        emails.push('"' + displayName + '"<' + this.v + '>');
      }
    });
    return emails;
  }

  function _createAndOpenEmail(emails, ambulance, body='Liebe KollegInnen,\n\n', focus='bcc') {
    var bcc = emails.join(',');
    moment().locale('de');
    var subject = ambulance.title + " am " + moment(ambulance.start).format('dd, D.M.YY') + " (" + ambulance.id_original + ")";
    var link = 'mailto:?' + focus + '=' + encodeURIComponent(bcc) + '&subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);
    window.open(link, target='_blank');
  }

  var spamEveryone = function(ambulance) {
    var spinner = new Spinner().spin()  // options see http://spin.js.org
    $('body').after(spinner.el);

    var requests = Array();
    var members = Array();
    $('a[href^="Javascript:SEmpFID"]').each(function() {
      var member = getEmployeeDataFromLink(this, 'EmployeeID');
      members.push(member);
      requests.push($.get(member.url));
    });

    var defer = $.when.apply($, requests);
    defer.done(function(){
        // This is executed only after every ajax request has been completed

        var emails = Array();
        $.each(arguments, function(index, responseData){
            // "responseData" will contain an array of response information for each specific request
            var employee = scrapeEmployee($.parseHTML(responseData[0]), members[index].url);
            Array.prototype.push.apply(emails, _getEmailsfromEmployeeData(employee, members[index]['displayName']));
        });

        if (emails.length > 0) {
          _createAndOpenEmail(emails, ambulance);
        } else {
          alert("Leider wurden keine Emails gefunden.");
        }

        spinner.stop();
    });
  }

  var mailToSomeone = function(ambulance, e) {
    var spinner = new Spinner().spin()  // options see http://spin.js.org
    $('body').after(spinner.el);

    var member = getEmployeeDataFromLink($(e).parent().find('a').first(), 'EmployeeID');
    $.get(member.url, function(data) {
      var employee = scrapeEmployee($.parseHTML(data), member.url);
      var emails = getAllEmails(employee.contacts, member['displayName']);

      if (emails.length > 0) {
        var body = 'Hallo ' + employee.nameFirst + ',\n\n'
        _createAndOpenEmail(emails, ambulance, body, 'to');
      } else {
        alert("Leider wurde für " + member['displayName'] + " keine Email gefunden.");
      }

      spinner.stop();
    })
  }

  var textToSomeone = function(ambulance, e) {
    var spinner = new Spinner().spin()  // options see http://spin.js.org
    $('body').after(spinner.el);

    var member = getEmployeeDataFromLink($(e).parent().find('a').first(), 'EmployeeID');
    $.get(member.url, function(data) {
      var employee = scrapeEmployee($.parseHTML(data), member.url);
      console.log(getDefaultPhone(employee.contacts));
      var fon = getDefaultPhone(employee.contacts);

      if (fon) {
        window.open("https://api.whatsapp.com/send?phone=" + fon.replace(/[^0-9]/g, ''))
      } else {
        alert("Leider wurde für " + member['displayName'] + " keine Telefonnummer gefunden.");
      }

      spinner.stop();
    })
  }

  var createSheet = function(ambulance, e) {

    $.modal.close();

    var spinner = new Spinner().spin()  // options see http://spin.js.org
    $('body').after(spinner.el);

    var saveData = (function () {
      var a = document.createElement("a");
      document.body.appendChild(a);
      a.style = "display: none";
      return function (blob, fileName) {
          var url = window.URL.createObjectURL(blob);
          a.href = url;
          a.download = fileName;
          a.click();
          window.URL.revokeObjectURL(url);
      };
    }());

    function s2ab(s) { 
      var buf = new ArrayBuffer(s.length); //convert s to arrayBuffer
      var view = new Uint8Array(buf);  //create uint8array as viewer
      for (var i=0; i<s.length; i++) view[i] = s.charCodeAt(i) & 0xFF; //convert to octet
      return buf;    
    }

    // create Workbook
    var wb = XLSX.utils.book_new();
    wb.Props = {
      Title: ambulance.title + " " + ambulance.id_original,
      Subject: "Test",
      Author: "WRK",  // TODO: add current User as author
      CreatedDate: new Date(),
    };

    var requests = Array();
    if($("#excelExportModal input:checkbox:checked").length > 0) {

      // create download links
      $.each(ambulance.employees, function(index, amb_mitarbeiter) {
        requests.push($.get(amb_mitarbeiter.Name.url));
      });

      // download all member data
      var defer = $.when.apply($, requests);

      // executed after all downloads completed
      defer.done(function() {
        $.each(arguments, function(index, responseData){
          // "responseData" will contain an array of response information for each specific request
          if(responseData !== undefined && ambulance.employees[index].Name.url !== undefined) {
            var employee = scrapeEmployee(parseHTMLOnly(responseData[0]), ambulance.employees[index].Name.url);
            ambulance.employees[index].permissions = employee.permissions;
            ambulance.employees[index].contacts = employee.contacts;
            ambulance.employees[index].phone = getDefaultPhone(employee.contacts);
            ambulance.employees[index].email = getDefaultEmail(employee.contacts);
          }
        });


        // create sheet header
        var ws_header = [
          "Position",
          "Funktion",
          "dNr",
          "Nachname",
          "Vorname",
        ];
        if ($('#chk_handy:checkbox:checked').length > 0)  ws_header.push("tel");          
        if ($('#chk_email:checkbox:checked').length > 0) ws_header.push("Email");          
        if ($('#chk_einsatzverwendung:checkbox:checked').length > 0)  ws_header.push("Einsatzverwendung");          
        if ($('#chk_san:checkbox:checked').length > 0)  ws_header.push("SAN");          
        if ($('#chk_sang:checkbox:checked').length > 0)  ws_header.push("SanG");          
        if ($('#chk_fahrerrd:checkbox:checked').length > 0)  ws_header.push("Fahrer RD"); 
        ws_header = ws_header.concat(["Url", "Ort", "Zeitpunkt", "Anmerkung"]);
        var ws_data = [ws_header];

        // add sheet data
        $.each(ambulance.employees, function() {
          var ws_row = [];
          ws_row.push(this.Position);
          ws_row.push(this.Funktion);
          ws_row.push(this.dNr);
          ws_row.push(this.Name.lastName);
          ws_row.push(this.Name.firstName);
          if ($('#chk_handy:checkbox:checked').length > 0) ws_row.push(this.phone);
          if ($('#chk_email:checkbox:checked').length > 0) ws_row.push(this.email);
          if (this.permissions == undefined) {
            this.permissions = {};
          }
          if ($('#chk_einsatzverwendung:checkbox:checked').length > 0) ws_row.push(this.permissions.Einsatzverwendung);
          if ($('#chk_san:checkbox:checked').length > 0) ws_row.push(this.permissions.SAN);
          if ($('#chk_sang:checkbox:checked').length > 0) ws_row.push(this.permissions.SanG);            
          if ($('#chk_fahrerrd:checkbox:checked').length > 0) ws_row.push(this.permissions["Fahrer RD"]);                    
          ws_row.push(this.Name.url);
          ws_row.push(this.Abfahrt.Ort);
          ws_row.push(this.Abfahrt.Zeitpunkt);
          ws_row.push(this.Anmerkung);
          ws_data.push(ws_row);
        });

        // Add sheet to workbook
        var sheetName = "Subtag " + ambulance.sub; // creates Subtag Sheet
        wb.SheetNames.push(sheetName);
        var ws = XLSX.utils.aoa_to_sheet(ws_data);
        $.each(Object.keys(ws).filter(function (cellName) {return cellName.indexOf("N") === 0;}), function() {
          ws[this].z = "m.d.yy hh:mm";
        });
        // Verlinkung funktioniert nicht
        /* $.each(Object.keys(ws).filter(function (cellName) {return cellName.indexOf("L") === 0;}), function() {
          if(this!=="L1") {
            ws[this].l = { Target:ws[this].v, Tooltip:"Link zum NiU Profil" };
          } 
        }); */
        console.log(ws);
        wb.Sheets[sheetName] = ws;
        
        // Save Sheet as File
        var fileName = sanitize(`${ambulance.title}_${ambulance.id_original}.xlsx`);
        var wbout = XLSX.write(wb, {bookType:'xlsx',  type: 'binary'});
        var blob = new Blob([s2ab(wbout)],{type:"application/octet-stream"});
        saveData(blob, fileName);

        spinner.stop();
      });
    }
  }

  var ambulance = scrapeAmbulance();

  // Hidden Modal for Excel export
  $('body').append("<div id='excelExportModal' class='modal'></div>");
  $('div#excelExportModal').append('<h2>Excel Export Optionen</h2>');
  $('div#excelExportModal').append('<input type="checkbox" id="chk_einsatzverwendung" style="margin-left:1.5em;margin-right:0.2em;vertical-align:middle;" checked>Einsatzverwendung</input><br/>');
  $('div#excelExportModal').append('<input type="checkbox" id="chk_san" style="margin-left:1.5em;margin-right:0.2em;vertical-align:middle;" checked>SAN</input><br/>');
  $('div#excelExportModal').append('<input type="checkbox" id="chk_sang" style="margin-left:1.5em;margin-right:0.2em;vertical-align:middle;" checked>SanG</input><br/>');
  $('div#excelExportModal').append('<input type="checkbox" id="chk_fahrerrd" style="margin-left:1.5em;margin-right:0.2em;vertical-align:middle;" checked>Fahrer RD</input><br/>');
  $('div#excelExportModal').append('<input type="checkbox" id="chk_handy" style="margin-left:1.5em;margin-right:0.2em;vertical-align:middle;" checked>Handy</input><br/>');
  $('div#excelExportModal').append('<input type="checkbox" id="chk_email" style="margin-left:1.5em;margin-right:0.2em;vertical-align:middle;" checked>Email</input><br/>');
  $('div#excelExportModal').append('<button id="createSheet" style="font-weight:bold;margin-top:5px">Download</button>');
  

  $('h1').append('<a href="#" id="spamspamspam">' + mailImage + '<span style="position:relative;top:1px;left:1px;">Email an Alle</span></a>')

  $('h1').append('<br /><a href="#excelExportModal" rel="modal:open">' + xlsxImage + '<span style="position:relative;top:1px;left:1px;">Excel</span></a>')

  $('a[href^="Javascript:SEmpFID"]').each(function() {
    $(this)
      .after('<a href="#" style="float: right;" class="mailToSomeone">' + mailImage + '</a>')
      .after('<a href="#" style="float: right;" class="textToSomeone">' + whatsappImage + '</a>')
  });

  $("#spamspamspam").click(function(e) {
    e.preventDefault();
    spamEveryone(ambulance);
  });

  $(".mailToSomeone").click(function(e) {
    e.preventDefault();
    mailToSomeone(ambulance, this);
  })

  $(".textToSomeone").click(function(e) {
    e.preventDefault();
    textToSomeone(ambulance, this);
  })

  $("#createSheet").click(function(e) {
    e.preventDefault();
    createSheet(ambulance, this);
  })

});

};

// ===== src/content_scripts/AmbulancesOpenPositions.js =====
__SCRIPTS["src/content_scripts/AmbulancesOpenPositions.js"] = function () {
$(document).ready(function () {

  // scrapes the table data
  // and enriches the rows with metadata
  // to enable filtering
  function prepareTable() {
    var positions = [];

    // set uniqe id for each header table
    var $tables = $('table.InnerBorder');
    $tables.find('a').each(function (i) {
      var tableHeaderID = $(this).attr('id').replace('_AmbNr', '');
      $($tables[i]).attr('group', tableHeaderID).attr('row-type', "header"); // add id to table
      $('table[group=' + tableHeaderID + ']').addClass('ambuTable');
    });

    // set uniqe id for each positions table
    $(document).find('table.openPositionsSubTable').each(function (i, $table) {
      var tableHeaderID = $(this).find('tr').first().attr('id').substring(0, $(this).find('tr').first().attr('id').indexOf('_rPositions'));

      $(this).find('tr').each(function () {
        $($table).attr('group', tableHeaderID).attr("row-type", "details");
        var position = $(this).find('td span').first().text();  // gesuchte Position zb UO, AZUBI
        $('table[group=' + tableHeaderID + ']').attr(position, true).addClass('ambuTable');
        positions.push(position);
      });
    });

    return Array.from(new Set(positions)).sort();
  }

  function filterTable() {
    if ($('#TableHack input:checkbox:checked').length) {
      $('table.ambuTable').hide();
      $('.TableHack.Position').each(function () {
        var positionID = $(this).attr('positionID');
        if ($(this).is(':checked')) {
          $('table[' + positionID + '=true]').show();
        }
      });
    } else {
      $('table.ambuTable').show();  // no checkbox select show all
    }

    var hideDays = [];

    $("[name='nlh_day_filter[]']").each(function () {
      var $this = $(this);
      var val = $this.val();
      var $label = $("#label_nlh_day_filter_" + val);

      if (!$this.prop("checked")) {
        hideDays.push(val);
        $label.css("font-weight", "normal");
      }
      else {
        $label.css("font-weight", "bold");
      }
    });

    if (hideDays && hideDays.length) {
      for (var i = 0; i < hideDays.length; i++) {
        var hideDayShort = hideDays[i];
        $("[day*='[" + hideDayShort + "]']").hide();
      }
    }

    $(".TableHack.DayRange").each(function () {
      var $this = $(this);

      if ($this.prop("checked")) {
        switch ($this.attr("id")) {
          case "day_range_all":
            $(".DayRangeSelector").prop("disabled", true);
            break;

          case "day_range_select":
            $(".DayRangeSelector").prop("disabled", false);
            var date_begin = $("[name=range_begin]").val();
            var date_end = $("[name=range_end]").val();
            $('table.ambuTable').each(function () {
              var $this = $(this);
              var row_date = $this.attr("date");

              if (row_date < date_begin || row_date > date_end) {
                $this.hide();
              }
            });
            break;

        }

        console.log($this.attr("id"));
      }
    });
  }

  tbl = prepareTable();
  $(".InnerBorder br").addClass('in_table');

  $("br:not('.in_table')").remove();
  $('table.openPositionsSubTable')
      .css('width', '100%')
      .css('margin-bottom', '0.9em');

  var days = [
    {short: 'So', name: 'Sonntag', order: 7},
    {short: 'Mo', name: 'Montag', order: 1},
    {short: 'Di', name: 'Dienstag', order: 2},
    {short: 'Mi', name: 'Mittwoch', order: 3},
    {short: 'Do', name: 'Donnerstag', order: 4},
    {short: 'Fr', name: 'Freitag', order: 5},
    {short: 'Sa', name: 'Samstag', order: 6}
  ];

  $("[row-type='header']").each(function () {
    $(this).find('td:contains("Einsatzbeginn"),td:contains("Von"),td:contains("Bis")').each(function () {
      var $this = $(this);
      var time = $this.text();
      var EB = false;
      if (time.search(/einsatzbeginn/i) != -1) {
        EB = true;
      }
      time = time.replace(/(einsatzbeginn|von|bis)/i, "");

      time = time.split(" ");
      var date = time[0].split('.');

      date = new Date(date[2] + '-' + date[1] + '-' + date[0] + 'T' + time[1]);
      time = time.join(" ");

      var day = days[date.getDay()].short;

      var html = $this.html().replace(time, day + " " + time);

      $this.html(html);

      var $table = $this.closest("table[row-type='header']");
      var $group = $("[group=" + $table.attr("group") + "]");

      var current = $group.attr("day");

      if (typeof current === 'undefined') {
        current = "";
      }

      day = "[" + day + "]";
      if (current.indexOf(day) == -1) {
        $group.attr("day", (current + day).trim());
      }

      if (EB) {
        $group.attr("date", date.toISOString().slice(0, 10));
      }
    });
  });

  // add selectors
  $('#aspnetForm div').slice(1).first().addClass("amb_list").prepend('<table class="DFTable" style="float:left;margin-bottom:0.9em;margin-top:1em;width:100%;"><tr><td><div id="TableHack" style="text-align:left;"></div></td></tr></table>');
  $.each(tbl, function () {
    $('#TableHack').append('<span style="white-space:nowrap;vertical-align: middle;padding-right:0.5em;"><label for="pos_' + this + '">' + this + '</label>: <input type="checkbox" id="pos_' + this + '" positionID="' + this + '" class="TableHack Position" style="margin-right:0.6em;vertical-align:middle;top:0.005em;"></span><wbr>')
  });

  var FilterContainer =
      "<div style='clear:both; font-weight:bold; text-align:left; border-top: 1px solid black; line-height: 150%;'></div>";

  var $FilterDay = $(FilterContainer)
      .html("Nur Dienste an folgenden Tagen:");
  $("<br/>").appendTo($FilterDay);

  var DayFilters = [];
  for (var dayIndex in days) {
    var day = days[dayIndex];
    var id = "nlh_day_filter_" + day.short;

    var $FilterItem = $("<div/>")
        .css("display", "inline-block")
        .css("padding", "0 2px");

    $("<input/>")
        .attr("type", "checkbox")
        .attr("name", "nlh_day_filter[]")
        .attr("id", id)
        .attr("checked", true)
        .addClass('TableHack Day')
        .val(day.short)
        .appendTo($FilterItem);

    $("<label/>")
        .attr("for", id)
        .attr("id", "label_" + id)
        .html(day.name)
        .css("vertical-align", "top")
        .css("font-weight", "bold")
        .appendTo($FilterItem);

    DayFilters[day.order] = $FilterItem;
  }

  for (dayIndex in DayFilters) {
    $FilterDay.append(DayFilters[dayIndex]);
  }

  var $FilterTable = $("div.amb_list table.DFTable");
  $FilterTable.append($("<tr/>").html("<td/>").html($FilterDay));

  var $FilterDateRange = $(FilterContainer)
      .html("Einsatzbeginn:");
  $("<br/>").appendTo($FilterDateRange);


  $("<div/>")
      .css("display", "inline-block")
      .css("padding", "0 2px")
      .append(
          $("<input/>")
              .addClass("TableHack DayRange")
              .attr("type", "radio")
              .attr("checked", "Checked")
              .attr("name", "day_range")
              .attr("id", "day_range_all")
      )
      .append(
          $("<label/>")
              .attr("for", "day_range_all")
              .html("Alle")
              .css("vertical-align", "top")
      )
      .appendTo($FilterDateRange);
  $("<div/>")
      .css("display", "inline-block")
      .css("padding", "0 2px")
      .append(
          $("<input/>")
              .addClass("TableHack DayRange")
              .attr("type", "radio")
              .attr("name", "day_range")
              .attr("id", "day_range_select")
      )
      .append(
          $("<label/>")
              .attr("for", "day_range_select")
              .html("Zwischen: ")
              .css("vertical-align", "top")
      )
      .appendTo($FilterDateRange);

  var today = new Date();
  var next_month = new Date(
      today.getFullYear(),
      today.getMonth() + 1,
      today.getDate(),
      today.getHours(),
      today.getMinutes(),
      today.getSeconds()
  );

  $("<div/>")
      .css("display", "inline-block")
      .css("padding", "0 2px")
      .append(
          $("<input/>")
              .addClass("TableHack DayRangeSelector")
              .css("display", "text-bottom")
              .css("border", "1px black solid")
              .attr("type", "date")
              .val(today.toISOString().slice(0, 10))
              .attr("name", "range_begin")
              .prop("disabled", true)
      )
      .append(" und ")
      .append(
          $("<input/>")
              .addClass("TableHack DayRangeSelector")
              .css("display", "text-bottom")
              .css("border", "1px black solid")
              .attr("type", "date")
              .val(next_month.toISOString().slice(0, 10))
              .attr("name", "range_end")
              .prop("disabled", true)
      )
      .appendTo($FilterDateRange);

  $FilterTable.append($("<tr/>").html("<td/>").html($FilterDateRange));

  $('.TableHack').change(function () {
    filterTable();
  });

  $('a[id^="ctl00_main_rAmbulances_ctl"]').attr('target', '_blank');

});

};

// ===== src/content_scripts/detailEmployee.js =====
__SCRIPTS["src/content_scripts/detailEmployee.js"] = function () {
$(document).ready(function() {
  console.log("detailEmployee content script called");

  // Alarm für noch nciht ausgefolgte Urkunden und Dekrete
  var load = {};
  load[STORAGE_KEY_DEKRET_ALERT] = DEFAULT_DEKRET_ALERT;
  chrome.storage.sync.get(load, function(item) {
    if (item[STORAGE_KEY_DEKRET_ALERT]) {
      var dekretAlarm = [];
      $("span[id$='_m_DescriptionLabel']:contains('nicht ausgefolgt')").each(function() {
        var dekretName = $(this).parent().parent().parent().parent().find("td").first().text();
        var dekretDatum = $(this).parent().parent().parent().parent().find("input").first().val();
        dekretAlarm.push("<b>" + dekretName + "</b> vom " + dekretDatum);
      });
      if(dekretAlarm.length>0) {
        var modalDiv = '<ul style="margin:10px 0px;list-style-position:inside;padding-left:.5em;">';
        $.each(dekretAlarm, function() {
          modalDiv += '<li style="margin-bottom:10px;">' + this + "</li>";
        });
        modalDiv += '</ul>';
        new PNotify({
          title: 'Dekrete noch nicht ausgefolgt:',
          text: modalDiv,
          type: "info",
          width: "400px",
        });
      }
    }
  });

  var person_data = {};

  getKuerzel().then(function(kuerzel) {
    person_data.admin_kuerzel = kuerzel;
  });

  getOwnName().then(function(name) {
    person_data.admin_name = name;
  });

  getOwnDNRs().then(function(dnrs){
    person_data.admin_dnr = dnrs[0];
  });

  person_data.anrede = $('#ctl00_main_m_Employee_m_ccEmployeeMain__salutation option:selected').text();  // Herr/Frau
  person_data.vorname = $('#ctl00_main_m_Employee_m_ccEmployeeMain__firstName').val();
  person_data.nachname = $('#ctl00_main_m_Employee_m_ccEmployeeMain__lastName').val();
  person_data.berufstitel = $('#ctl00_main_m_Employee_m_ccEmployeeMain__professionTitle option:selected').text();
  person_data.titel = $('#ctl00_main_m_Employee_m_ccEmployeeMain__preAcademicTitle option:selected').text();
  person_data.PGtitel = $('#ctl00_main_m_Employee_m_ccEmployeeMain__postAcademicTitle option:selected').text();

  person_data.strasse = $('#ctl00_main_m_Employee_m_ccPersonAddress_m_ccAddress0_m_Street').val();
  person_data.hausnummer = $('#ctl00_main_m_Employee_m_ccPersonAddress_m_ccAddress0_m_StreetNumber').val();
  person_data.plz = $('#ctl00_main_m_Employee_m_ccPersonAddress_m_ccAddress0_m_PostalCode').val();
  person_data.ort = $('#ctl00_main_m_Employee_m_ccPersonAddress_m_ccAddress0_m_City').val();
  person_data.land = $('#ctl00_main_m_Employee_m_ccPersonAddress_m_ccAddress0_m_Country option:selected').text();

  person_data.dienstgrad_kurz = $('#ctl00_main_m_Employee_m_ccEmployeeMain__rank  option:selected').text();
  person_data.dienstgrad = dienstgrade[person_data.dienstgrad_kurz];
  person_data.mindestdienstzahl = $('#ctl00_main_m_Employee_m_ccEmployeeExtention__annualMinDuties').val();

  person_data.geburtsdatum = $('#ctl00_main_m_Employee_m_ccEmployeeExtention__birthday_m_Textbox').val();

  person_data.ad_benutzername = $('#ctl00_main_m_Employee_m_ccEmployeeExtention_m_Employee tr:contains("AD Benutzername:") td:last').text();

  // Volle Anschrift mit Zeilenumbrüchen
  person_data.anschrift = person_data.strasse + " " + person_data.hausnummer + "\n" + person_data.plz + " " + person_data.ort + "\n" + person_data.land;

  // Kontodaten
  person_data.konto_inhaber = $('#ctl00_main_m_Employee_m_ucAccount_m_Name').val();
  person_data.konto_iban = $('#ctl00_main_m_Employee_m_ucAccount_m_Iban').val();
  person_data.konto_bank = $('#ctl00_main_m_Employee_m_ucAccount_m_BankName').val();
  person_data.konto_bic = $('#ctl00_main_m_Employee_m_ucAccount_m_Bic').val();

  // Geschlecht
  person_data.geschlecht = "";
  person_data.anrede_lieber = "Hallo";
  if (person_data.anrede == "Herr") {
    person_data.geschlecht = "m";
    person_data.anrede_lieber = "Lieber";
  }
  else if (person_data.anrede == "Frau") {
    person_data.geschlecht = "w";
    person_data.anrede_lieber = "Liebe";
  }

  // generiert den vollen Namen eg Oberstudienrätin Dr. Mag. Karin Muster, MBA
  person_data.name = "";
  if (person_data.berufstitel != '<Berufstitel>') {
    person_data.name += person_data.berufstitel + " ";
  }
  else {
    person_data.berufstitel = "";
  }
  if (person_data.titel != '<Titel>') {
    person_data.name += person_data.titel + " ";
  }
  else {
    person_data.titel = "";
  }
  person_data.name += person_data.vorname + " ";
  person_data.name += person_data.nachname + " ";
  if (person_data.PGtitel != '<Titel>' && person_data.PGtitel.trim() != "") {
    person_data.name += ", " + person_data.PGtitel;
  }
  else {
    person_data.PGtitel = "";
  }
  person_data.name = person_data.name.trim();

  // dienstnummer
  person_data.dienstnummer = $('h1').text().substring($('h1').text().indexOf('(') + 1, $('h1').text().indexOf(')'));

  console.log(person_data);

  // Template Box erstellen
  $('#ctl00_main_m_Employee_m_ccEmployeeMain__employeeMain').after('<hr><span id="template_box"><h2>Brief erstellen:</h2></span>');
  $('#template_box').append('<input type="file" id="upload_select_docx" accept="application/vnd.openxmlformats-officedocument.wordprocessingml.document" /><a href="' + chrome.extension.getURL("/src/webcontent/template_help.html") + '" rel="modal:open">' + helpImage + '</a>');

  // Copybox für Adresse
  new ClipboardJS('#adr_copy');
  $('#template_box').before('<span id="copybox" style="float:right;display:inline-flex;;"><textarea rows="4" cols="77" style="font-size:80%;" id="copycontent">' + person_data.name + "\n" + person_data.anschrift + '</textarea><span>');
  $('#copybox').append('<a href="#" id="adr_copy" data-clipboard-target="#copycontent">' + copyImage + '</a>');
  
  //event listener for when the input changes
  document.querySelector("#upload_select_docx").addEventListener('change',loadDocX, false);

  function loadFile(url,callback){
    JSZipUtils.getBinaryContent(url,callback);
  }

  function loadDocX(evt){
    var url;
    var file;
    file = evt.target.files[0];
    reader = new FileReader();
    //we need to instantiate a new FileReader object
    reader.addEventListener("load", readDocx, false);
    //we add an event listener for when a file is loaded by the FileReader
    //this will call our function 'readDocx()'
    
    reader.readAsDataURL(file);
    //we now read the data
  }
  function readDocx(event) {
    // event.target.result;
    //the event has a target property, the FileReader with a property 'result',
    //which is where the value we read is located

    loadFile(event.target.result,function(error, content){
      var filedate = (new Date()).toISOString().slice(0,10).replace(/-/g,"");
      var template_name = $("#upload_select_docx").val().replace("C:\\fakepath\\", "");
      var output_filename = [filedate, person_data.dienstnummer, person_data.nachname, person_data.vorname, template_name].join("_");
      if (error) { throw error };
      var zip = new JSZip(content);
      var doc = new Docxtemplater().loadZip(zip)
      doc.setData(person_data);
      try {
          // render the document (replace all occurences of {first_name} by John, {last_name} by Doe, ...)
          doc.render()
      }
      catch (error) {
          var e = {
              message: error.message,
              name: error.name,
              stack: error.stack,
              properties: error.properties,
          }
          console.log(JSON.stringify({error: e}));
          // The error thrown here contains additional information when logged with JSON.stringify (it contains a property object).
          throw error;
      }
      var out=doc.getZip().generate({
          type:"blob",
          mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      }) //Output the document using Data-URI
      saveAs(out, output_filename)
  });
  }
});

};

// ===== src/content_scripts/intranet.wrk.at/vfm-bescheiderstellung.js =====
__SCRIPTS["src/content_scripts/intranet.wrk.at/vfm-bescheiderstellung.js"] = function () {
$(document).ready(function() {
  console.log("vfm-bescheiderstellung content script called");


  $('#main-content').after('<hr><span id="template_box"><h2>Bescheidvorlage:</h2></span>');
  
  $('#template_box').append('<input type="file" id="upload_select_docx" accept="application/vnd.openxmlformats-officedocument.wordprocessingml.document" /><input type="button" id="generatebutton" value="Bescheid erstellen" /><br /><sub>Sobald hier eine Bescheidvorlage eingefügt wird, startet automatisch der Download des fertig erstellten Bescheids.<br />Die in der Vorlage verwendeten Platzhalter werden automatisch mit den im Formular eingegebenen Daten ersetzt.</sub>');

  //event listener for when the input changes
  document.querySelector("#upload_select_docx").addEventListener('change',loadDocX, false);
  document.querySelector("#generatebutton").addEventListener('click',generateButtonClicked, false);

  function generateButtonClicked()
  {
    document.querySelector("#upload_select_docx").value = "";
    document.querySelector("#upload_select_docx").click();
  }

  function loadFile(url,callback){
    JSZipUtils.getBinaryContent(url,callback);
  }

  function loadDocX(evt){
    var url;
    var file;
    file = evt.target.files[0];
    reader = new FileReader();
    //we need to instantiate a new FileReader object
    reader.addEventListener("load", readDocx, false);
    //we add an event listener for when a file is loaded by the FileReader
    //this will call our function 'readDocx()'
    
    reader.readAsDataURL(file);
    //we now read the data
  }
  function readDocx(event) {
    // event.target.result;
    //the event has a target property, the FileReader with a property 'result',
    //which is where the value we read is located

    loadFile(event.target.result,function(error, content){
      
      var person_data = {};

      var def_fieldnames = $("#i_fieldnames").val().split(";");
      var def_filename = $("#i_filename").val().split(";");
      var def_dropdowns = $("#i_dropdowns").val().split(";")
      
      var filename_constructed = "";

      for(var i = 0; i < def_filename.length; i++)
      {
        def_filename[i] = $("#i_" + def_filename[i]).val();
      }

      filename_constructed = def_filename.join("_");

      for(var i = 0; i < def_fieldnames.length; i++)
      {
        person_data[def_fieldnames[i]] = $("#i_" + def_fieldnames[i]).val();
      }

      for(var i = 0; i < def_dropdowns.length; i++)
      {
        person_data[def_dropdowns[i]] = $("#i_" + def_dropdowns[i] + " option:selected").text();
      }

      var filedate = (new Date()).toISOString().slice(0,10).replace(/-/g,"");
      var template_name = $("#upload_select_docx").val().replace("C:\\fakepath\\", "");

      if (error) { throw error };
      var zip = new JSZip(content);
      var doc = new Docxtemplater().loadZip(zip)
      doc.setData(person_data);
      try {
          // render the document (replace all occurences of {first_name} by John, {last_name} by Doe, ...)
          doc.render()
      }
      catch (error) {
          var e = {
              message: error.message,
              name: error.name,
              stack: error.stack,
              properties: error.properties,
          }
          console.log(JSON.stringify({error: e}));
          // The error thrown here contains additional information when logged with JSON.stringify (it contains a property object).
          throw error;
      }
      var out=doc.getZip().generate({
          type:"blob",
          mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      }) //Output the document using Data-URI
      saveAs(out, filename_constructed + ".docx")
  });
  }

});
};

// ===== src/content_scripts/EmployeeDutyStatistic.js =====
__SCRIPTS["src/content_scripts/EmployeeDutyStatistic.js"] = function () {
// jscs:disable maximumLineLength

$(document).ready(function() {

  // sorts an object by it's value
  // returns array
  function sortProperties(obj) {
    // convert object into array
    var sortable = [];
    for (var key in obj) {
      if (obj.hasOwnProperty(key)) {
        sortable.push([key, obj[key]]); // each item is an array in format [key, value]
      }
    }
    // sort items by value
    sortable.sort(function(a, b) {
      var x = a[1];
      var y = b[1];
      return x < y ? -1 : x > y ? 1 : 0;
    });

    return sortable; // array in format [ [ key1, val1 ], [ key2, val2 ], ... ]
  }

  // scrapes the table data
  // and enriches the rows with metadata
  // to enable filtering
  function prepareTable() {

    // get your own Dienstnummer
    var dienstnummer = $('h3').first().text().substring($('h3').first().text().indexOf('(')).replace('(', '').replace(')', '').trim();
    console.log('Dienstnummer: ' + dienstnummer);

    // iterate data of each row
    var $tables = $('div.MultiDutyRoster');
    $tables.find('table.MessageTable').each(function(i) {

      // add placholder for statistics
      $(this).find('tbody tr').first().after('<tr><td><table class="DutyRoster" cellspacing="0" cellpadding="3" rules="all" border="1"><tbody><tr><td id="charts' + i + '"></td></tr></tbody></table></td></tr>');

      // add header for duty duration
      $(this).find('td.DRCTime').first().after('<td class="DRCDuration" width="50px">Dauer</td>');

      var tableType = $(this).find('td.MessageHeader').text();

      // create statistical counters
      var rawWochentag = new Array();
      var rawDienststellen = new Array();
      var currentDateString;
      var sumDuty = 0; // Gesamtdauer aller Dienste
      var countDienste = 0;
      var rawKollegen = new Array();
      var rawDutyAs = new Array();

      $(this).find('table#DutyRosterTable tbody tr').each(function() {
        countDienste += 1;
        $(this).find('td').each(function(i, val) {
          val = val.innerHTML.replace('&nbsp;', '').replace('<em>', '').replace('</em>', '').trim();
          switch (i) {
            case 0: // Wochentag
              rawWochentag.push(val);
              break;
            case 1: // Datum
              currentDateString = val;
              break;
            case 2: // Zeiten
              hours = getDurationFromTimeString(currentDateString, val);
              $(this).after('<td>' + hours + '</td>');
              sumDuty += hours;
              break;
            case 3: // Dienststellen
              rawDienststellen.push(val);
              break;
            default:
              break;
          }
          if (tableType.includes('geplant')) {
            switch (i) {
              case 4: // Fahrer
              case 5: // SAN1
              case 6: // SAN2, Error Try-Catch um bei 2-spaltigen Dienstarten keinen Programmabbruch zu verursachen.
                try {
                  if (!$(val).text().includes(dienstnummer) && $(val).text() !== '') {
                    var kollege = $(val).text().substring(0, $(val).text().indexOf('(')).replace('Wunschmeldung', '').replace(':', '').replace('>', '').trim();
                    rawKollegen.push(kollege);
                  } else if ($(val).text() !== '') {
                    switch (i) {
                      case 4: // SEF
                        rawDutyAs.push('SEF');
                        break;
                      case 5: // SAN1
                        rawDutyAs.push('SAN1');
                        break;
                      case 6: // SAN2
                        rawDutyAs.push('SAN2');
                        break;
                      default:
                        break;
                    }
                  }
                  break;
                }
                catch (err) {
                  console.log(err);
                  break;
                }
              default:
                break;
            }
          } else if (tableType.includes('fixiert')) {
            switch (i) {
              case 5: // Fahrer
              case 6: // SAN1
              case 7: // SAN2, Error Try-Catch um bei 2-spaltigen Dienstarten keinen Programmabbruch zu verursachen.
                try {
                  if (!$(val).text().includes(dienstnummer) && $(val).text() !== '') {
                    var kollege = $(val).text().substring(0, $(val).text().indexOf('(')).trim();
                    rawKollegen.push(kollege);
                  } else if ($(val).text() !== '') {
                    switch (i) {
                      case 5: // SEF
                        rawDutyAs.push('SEF');
                        break;
                      case 6: // SAN1
                        rawDutyAs.push('SAN1');
                        break;
                      case 7: // SAN2
                        rawDutyAs.push('SAN2');
                        break;
                      default:
                        break;
                    }
                  }
                  break;
                }
                catch (err) {
                  break;
                }
              default:
                break;
            }
          }
        });
      });

      // var countWochentag = {};
      // rawWochentag.forEach(function(x) { countWochentag[x] = (countWochentag[x] || 0) + 1; });
      // $('#charts' + i).append('<span class="WochentagChart' + i + '"></span>');
      // var data = {
      //   labels: Object.keys(countWochentag),
      //   series: Object.values(countWochentag),
      // };
      // var options = {
      //   width: '200',
      //   showLabel: true,
      //   ignoreEmptyValues: true,
      // };
      // new Chartist.Pie('.WochentagChart' + i, data, options);

      var countDienststellen = {};
      var countPercDienststellen = {};
      rawDienststellen.forEach(function(x) { countDienststellen[x] = (countDienststellen[x] || 0) + 1; });
      console.log(countDienststellen);
      Object.keys(countDienststellen).forEach(function(key,index) {
        // calculate percentage
        var perc = key + ' (' + Math.round(countDienststellen[key] / rawDienststellen.length * 100) + '%)';
        countPercDienststellen[perc] = countDienststellen[key];
      });
      $('#charts' + i).append('<table style="float:left;"><thead><tr><td style="text-align:center;"><strong>Dienst auf:</strong></td></tr></thead></tbody><tr><td class="DienststellenChart' + i + '"></td></tr></tbody></table>');
      var data = {
        labels: Object.keys(countPercDienststellen),
        series: Object.values(countPercDienststellen),
      };
      var options = {
        width: '200',
        showLabel: true,
        ignoreEmptyValues: true,
      };
      new Chartist.Pie('.DienststellenChart' + i, data, options);

      var countDutyAs = {};
      var countPercDutyAs = {};
      rawDutyAs.forEach(function(x) { countDutyAs[x] = (countDutyAs[x] || 0) + 1; });
      console.log(countDutyAs);
      Object.keys(countDutyAs).forEach(function(key,index) {
        // calculate percentage
        var perc = key + ' (' + Math.round(countDutyAs[key] / rawDutyAs.length * 100) + '%)';
        countPercDutyAs[perc] = countDutyAs[key];
      });
      $('#charts' + i).append('<table style="float:left;"><thead><tr><td style="text-align:center;"><strong>Dienst als:</strong></td></tr></thead></tbody><tr><td class="DutyAsChart' + i + '"></td></tr></tbody></table>');
      var data = {
        labels: Object.keys(countPercDutyAs),
        series: Object.values(countPercDutyAs),
      };
      var options = {
        width: '200',
        showLabel: true,
        ignoreEmptyValues: true,
      };
      new Chartist.Pie('.DutyAsChart' + i, data, options);

      var countKollegen = {};
      rawKollegen.forEach(function(x) { countKollegen[x] = (countKollegen[x] || 0) + 1; });
      countKollegenSorted = sortProperties(countKollegen);

      // $('text.ct-label').css('color', 'black');
      // $('text.ct-label').css('font-weight', 'bold');  // not working

      $('#charts' + i).append('<table style="float:left;"><thead><tr><td><strong>Übersicht:</strong></td></tr></thead><tbody class="additionalData' + i + '"><tr><td></td></tr></tbody></table>');
      $('.additionalData' + i).append('<tr><td>Dienste: </td><td style="text-align:right;">' + countDienste + '</td></tr>');
      $('.additionalData' + i).append('<tr><td>Gesamtdauer: </td><td style="text-align:right;">' + sumDuty + '</td></tr>');
      $('.additionalData' + i).append('<tr><td>durchschnittl. Dauer: </td><td style="text-align:right;">' + Math.round(sumDuty / countDienste) + '</td></tr>');

      $('#charts' + i).append('<table style="float:left;margin-left:20px;"><thead><tr><td><strong>Top KollegInnen:</strong></td></tr></thead><tbody class="topKollegen' + i + '"><tr><td></td></tr></tbody></table>');
      Object.keys(countKollegenSorted.reverse().slice(0,5)).forEach(function(key, object) {
        $('.topKollegen' + i).append('<tr><td>' + countKollegenSorted[key][0] + '</td><td style="text-align:right;">' + countKollegenSorted[key][1] + '</td></tr>');
      });
    });
  }

  function filterTable() {
    $('br').remove();
    $('table.openPositionsSubTable').css('width', '100%');
    $('table.openPositionsSubTable').css('margin-bottom', '0.9em');
    $('table.ambuTable').hide();
    $('.TableHack').each(function() {
      var positionID = $(this).attr('positionID');
      if ($(this).is(':checked')) {
        $('table[' + positionID + '=true]').show();
      }
    });
  }

  tbl = prepareTable();

});

};

